using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Set up options with a type-info resolver that only knows about "Person" ---
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Type handled : {personInfo.Type.Name}");
Console.WriteLine($"Kind         : {personInfo.Kind}");
Console.WriteLine($"Round-trip   : {JsonSerializer.Deserialize("""{"Name":"Ada"}""", personInfo)}\n");

// 2) Probe without throwing: TryGetTypeInfo() returns false instead of an exception.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"Person metadata found  -> {found!.Type.Name}");
else
    Console.WriteLine("Person metadata NOT found");

if (options.TryGetTypeInfo(typeof(UnknownWidget), out _))
    Console.WriteLine("UnknownWidget metadata found");
else
    Console.WriteLine("UnknownWidget metadata NOT found  (no exception thrown!)");

